exports.init = (params, rng) => {
  const N = params.vehicleCount;
  const L = params.roadLength;
  const l_veh = 5;
  const dt = 0.1;
  const maxDelaySteps = Math.ceil(2.5 / dt);
  const spacing = L / N;
  const gap_eq = spacing - l_veh;
  function Veq(s){
    if(s<=0) return 0;
    let s_c = params.safeHeadway * 2.5;
    let w = params.safeHeadway * 4;
    if(w<0.5) w=0.5;
    let tanh_sc_w = Math.tanh(s_c / w);
    let denom = 1 + tanh_sc_w;
    let val = Math.tanh((s - s_c)/w) + tanh_sc_w;
    let v_opt = params.desiredSpeed * val / denom;
    if(v_opt<0) v_opt=0;
    if(v_opt>params.desiredSpeed) v_opt=params.desiredSpeed;
    return v_opt;
  }
  let v_eq = Veq(gap_eq);
  let x=[]; let v=[];
  for(let i=0;i<N;i++){
    x.push(i*spacing);
    v.push(v_eq);
  }
  v[0] = Math.max(0, v[0] - params.perturbationSize);
  let history=[];
  for(let h=0; h<=maxDelaySteps; h++) history.push({x:x.slice(), v:v.slice()});
  return {t:0, x:x, v:v, history:history, dt:dt, l_veh:l_veh, jamPosHistory:[]};
};
exports.step = (state, params, rng) => {
  const N = params.vehicleCount;
  const L = params.roadLength;
  const dt = state.dt;
  const l_veh = state.l_veh;
  const tau = params.reactionDelay;
  const delaySteps = Math.round(tau / dt);
  function V(s){
    if(s<=0) return 0;
    let s_c = params.safeHeadway * 2.5;
    let w = params.safeHeadway * 4;
    if(w<0.5) w=0.5;
    let tanh_sc_w = Math.tanh(s_c / w);
    let denom = 1 + tanh_sc_w;
    let val = Math.tanh((s - s_c)/w) + tanh_sc_w;
    let v_opt = params.desiredSpeed * val / denom;
    if(v_opt<0) v_opt=0;
    if(v_opt>params.desiredSpeed) v_opt=params.desiredSpeed;
    return v_opt;
  }
  let histIdx = state.history.length - 1 - delaySteps;
  if(histIdx<0) histIdx=0;
  let delayed = state.history[histIdx];
  let newV=[]; let newX=[];
  const tau_adapt = 0.2;
  for(let i=0;i<N;i++){
    let leader = (i+1)%N;
    let x_i_d = delayed.x[i];
    let x_l_d = delayed.x[leader];
    let s_delayed = (x_l_d - x_i_d + L) % L - l_veh;
    let v_opt = V(s_delayed);
    let v_cur = state.v[i];
    let a = (v_opt - v_cur) / tau_adapt;
    let v_next = v_cur + a * dt;
    if(v_next<0) v_next=0;
    if(v_next>params.desiredSpeed*1.2) v_next=params.desiredSpeed*1.2;
    let s_cur = (state.x[leader] - state.x[i] + L) % L - l_veh;
    if(s_cur < 1.0 && v_next > s_cur/dt) v_next = Math.max(0, s_cur/dt*0.9);
    newV.push(v_next);
  }
  for(let i=0;i<N;i++){
    let xn = state.x[i] + newV[i]*dt;
    xn = ((xn % L)+L)%L;
    newX.push(xn);
  }
  let newHistory = state.history.slice();
  newHistory.push({x:newX.slice(), v:newV.slice()});
  const maxDelaySteps = Math.ceil(2.5/dt);
  if(newHistory.length > maxDelaySteps+1) newHistory.shift();
  let jamPosHistory = state.jamPosHistory.slice();
  let threshold=0.5;
  let slowIdx=[];
  for(let i=0;i<N;i++) if(newV[i] < threshold) slowIdx.push(i);
  if(slowIdx.length>0){
    let sumSin=0,sumCos=0;
    for(let idx of slowIdx){
      let ang = 2*Math.PI*newX[idx]/L;
      sumSin+=Math.sin(ang); sumCos+=Math.cos(ang);
    }
    let avgAng = Math.atan2(sumSin/slowIdx.length, sumCos/slowIdx.length);
    if(avgAng<0) avgAng+=2*Math.PI;
    let jamCenter = avgAng/(2*Math.PI)*L;
    jamPosHistory.push(jamCenter);
    if(jamPosHistory.length>100) jamPosHistory.shift();
  } else {
    jamPosHistory.push(null);
    if(jamPosHistory.length>100) jamPosHistory.shift();
  }
  return {t:state.t+dt, x:newX, v:newV, history:newHistory, dt:dt, l_veh:l_veh, jamPosHistory:jamPosHistory};
};
exports.observe = (state, params) => {
  const N = params.vehicleCount;
  const L = params.roadLength;
  let meanSpeed = state.v.reduce((a,b)=>a+b,0)/N;
  let threshold=0.5;
  let jamCount=0; let inJam=false;
  for(let i=0;i<N;i++){
    if(state.v[i] < threshold){ if(!inJam){ jamCount++; inJam=true; } } else { inJam=false; }
  }
  if(N>1 && state.v[0] < threshold && state.v[N-1] < threshold && jamCount>1) jamCount--;
  let waveSpeed=0;
  if(jamCount>0){
    const hist = state.jamPosHistory || [];
    const pts = [];
    for (let i = 0; i < hist.length; i++) if (hist[i] != null) pts.push({ i: i, x: hist[i] });
    if (pts.length >= 8) {
      const unwrapped = [pts[0].x];
      for (let k = 1; k < pts.length; k++) {
        let x = pts[k].x;
        const prev = unwrapped[unwrapped.length - 1];
        while (x - prev > L / 2) x -= L;
        while (prev - x > L / 2) x += L;
        unwrapped.push(x);
      }
      const start = Math.max(0, unwrapped.length - 40);
      const n = unwrapped.length - start;
      let sx = 0, sy = 0, sxx = 0, sxy = 0;
      for (let k = start; k < unwrapped.length; k++) {
        const t = pts[k].i;
        sx += t; sy += unwrapped[k]; sxx += t * t; sxy += t * unwrapped[k];
      }
      const den = n * sxx - sx * sx;
      if (Math.abs(den) > 1e-6) waveSpeed = ((n * sxy - sx * sy) / den) / (state.dt || 0.1);
    }
  }
  let density = N/L;
  let flowRate = density * meanSpeed * 3600;
  let variance = state.v.reduce((a,b)=>a+(b-meanSpeed)*(b-meanSpeed),0)/N;
  return {jamCount:jamCount, waveSpeed:waveSpeed, meanSpeed:meanSpeed, flowRate:flowRate, speedVariance:variance};
};
exports.view = (state, params) => {
  const L = params.roadLength;
  let bodies=[];
  for(let i=0;i<state.x.length;i++){
    bodies.push({id:'car'+i, x:(state.x[i]/L)*100, y:50, vx:state.v[i], vy:0, radius:1.5, color: state.v[i]<0.5 ? '#ff2222' : '#22cc22'});
  }
  return {kind:'bodies', bounds:{x:0,y:0,w:100,h:100}, bodies:bodies, roadLength:L, time:state.t};
};
